   156→    func test_query_engine() {
   157→        print("\n=== Test 2: Query Engine ===");
   158→
   159→        let s = make_users_schema();
   160→        let t = schema.table_new(s);
   161→
   162→        // 10개 행 삽입
   163→        let i = 0;
   164→        for i = 0; i < 10; i = i + 1 {
   165→            let row = make_user_row(
   166→                i64(i + 1),
   167→                "user_" + i32_to_str(i),
   168→                i64(20 + i * 2),
   169→                i % 2 == 0
   170→            );
   171→            t.table_insert(row);
   172→        }
   173→
   174→        // WHERE age > 25
   175→        let q1 = query.query_table(t);
   176→        q1.where_int(2, query.OP_GT, 25);
   177→        let r1 = query.execute(t, q1);
   178→        // age: 20,22,24,26,28,30,32,34,36,38 → >25 = 26,28,30,32,34,36,38 = 7개
   179→        let res1 = assert_eq_i32(r1.row_count, 7, "WHERE age>25 count==7");
   180→        print_result(res1);
   181→
   182→        // WHERE age >= 20 AND age <= 30
   183→        let q2 = query.query_table(t);
   184→        q2.where_int(2, query.OP_GE, 20);
   185→        q2.where_int(2, query.OP_LE, 30);
   186→        let r2 = query.execute(t, q2);
   187→        // age: 20,22,24,26,28,30 = 6개
   188→        let res2 = assert_eq_i32(r2.row_count, 6, "WHERE 20<=age<=30 count==6");
   189→        print_result(res2);
   190→
   191→        // ORDER BY age DESC, LIMIT 3
   192→        let q3 = query.query_table(t);
   193→        q3.order_by_int(2, false);  // age DESC
   194→        q3.set_limit(3);
   195→        let r3 = query.execute(t, q3);
   196→        let res3 = assert_eq_i32(r3.row_count, 3, "ORDER BY age DESC LIMIT 3 count==3");
   197→        print_result(res3);
   198→
   199→        // 첫 번째 결과가 가장 나이 많은 사람 (age=38)
   200→        let top_row = t.table_get_row(r3.row_indices[0]);
   201→        let res4 = assert_eq_i64(top_row.int_vals[1], 38, "DESC first row age==38");
   202→        print_result(res4);
   203→
   204→        // OFFSET + LIMIT (페이지 2)
   205→        let q4 = query.query_table(t);
   206→        q4.order_by_int(2, true);   // age ASC
   207→        q4.set_offset(3);
   208→        q4.set_limit(3);
   209→        let r4 = query.execute(t, q4);
   210→        let res5 = assert_eq_i32(r4.row_count, 3, "OFFSET 3 LIMIT 3 count==3");
   211→        print_result(res5);
   212→
   213→        // LIKE 쿼리: "user_1" 접두어 → "user_1" 1개
   214→        let q5 = query.query_table(t);
   215→        q5.where_str(1, query.OP_LIKE, "user_1");
   216→        let r5 = query.execute(t, q5);
   217→        let res6 = assert_true(r5.row_count >= 1, "LIKE 'user_1' count>=1");
   218→        print_result(res6);
   219→
   220→        print("Query engine tests completed");
   221→    }
