   225→    func test_aggregation() {
   226→        print("\n=== Test 3: Aggregation ===");
   227→
   228→        let s = make_users_schema();
   229→        let t = schema.table_new(s);
   230→
   231→        // 5개 행 삽입 (age: 10, 20, 30, 40, 50)
   232→        let i = 0;
   233→        for i = 0; i < 5; i = i + 1 {
   234→            let row = make_user_row(i64(i + 1), "user_" + i32_to_str(i), i64((i + 1) * 10), true);
