   353→    func test_transaction() {
   354→        print("\n=== Test 5: Transaction COMMIT & ROLLBACK ===");
   355→
   356→        let s = make_users_schema();
   357→        let t = schema.table_new(s);
   358→
   359→        // 시나리오 1: COMMIT
   360→        let tx1 = transaction.tx_begin();
   361→        let row1 = make_user_row(1, "Alice", 30, true);
   362→        let id1, err1 = transaction.tx_insert(&tx1, &t, row1);
