   369→
   370→        let _, found1 = t.table_get(id1);
   371→        let t3 = assert_true(found1, "committed row exists");
   372→        print_result(t3);
   373→
   374→        // 시나리오 2: ROLLBACK INSERT
   375→        let tx2 = transaction.tx_begin();
   376→        let row2 = make_user_row(2, "Bob", 25, false);
   377→        let id2, err2 = transaction.tx_insert(&tx2, &t, row2);
   378→
   379→        transaction.tx_rollback(&tx2, &t);
   380→        let t4 = assert_true(transaction.tx_is_rolled_back(tx2), "tx2 rolled back");
   381→        print_result(t4);
   382→
   383→        let _, found2 = t.table_get(id2);
   384→        let t5 = assert_true(!found2, "rolled back row not found");
   385→        print_result(t5);
   386→
   387→        // 시나리오 3: ROLLBACK UPDATE
   388→        let tx3 = transaction.tx_begin();
   389→        let err_upd = transaction.tx_update_int(&tx3, &t, id1, 2, 99);  // age → 99
   390→        let t6 = assert_true(err_upd == transaction.TX_OK, "tx_update_int ok");
   391→        print_result(t6);
   392→
   393→        // 롤백 전 확인
   394→        let before_rb, _ = t.table_get(id1);
   395→        let t7 = assert_eq_i64(before_rb.int_vals[1], 99, "age==99 before rollback");
   396→        print_result(t7);
   397→
   398→        transaction.tx_rollback(&tx3, &t);
