// ============================================================================
// FreeLang Phase 11 Integration Pipeline - End-to-End Tests
// ============================================================================
// 목표: schema → query engine → result set 통합 파이프라인 테스트
// 시나리오:
//   1. test_pipeline_select_all: 전체 행 선택 (SELECT * FROM)
//   2. test_pipeline_where: 조건부 선택 (WHERE 절)
//   3. test_pipeline_sort_limit: 정렬 및 페이징 (ORDER BY + LIMIT)
// 원리:
//   - 각 테스트는 독립적 테이블 생성
//   - schema.Table 생성 → 행 삽입 → query 실행 → 결과 검증
//   - 100% FreeLang 구현 (TypeScript/Go 의존성 없음)
// ============================================================================

module pipeline_test {
    // === 테스트 유틸리티 ===

    struct TestResult {
        name:    string;
        passed:  bool;
        message: string;
    }

    func assert_true(condition: bool, name: string) -> TestResult {
        return TestResult{
            name:    name,
            passed:  condition,
            message: if condition { "PASS" } else { "FAIL" },
        };
    }

    func assert_eq_i32(actual: i32, expected: i32, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i32_to_str(expected) + " got " + i32_to_str(actual) },
        };
    }

    func assert_eq_i64(actual: i64, expected: i64, name: string) -> TestResult {
        let passed = actual == expected;
        return TestResult{
            name:    name,
            passed:  passed,
            message: if passed { "PASS" } else { "FAIL: expected " + i64_to_str(expected) + " got " + i64_to_str(actual) },
        };
    }

    func print_result(r: TestResult) {
        let status = if r.passed { "[PASS]" } else { "[FAIL]" };
        print(status + " " + r.name + " - " + r.message);
    }

    // === 공통 헬퍼 함수 ===

    // 테이블 스키마 생성 (id, age 두 컬럼)
    func make_emp_schema() -> schema.TableSchema {
        let s = schema.schema_new("emp");
        s.schema_add_col("id",  schema.COL_TYPE_INT, false);
        s.schema_add_col("age", schema.COL_TYPE_INT, false);
        return s;
    }

    // 직원 행 생성
    func make_emp_row(id: i64, age: i64) -> schema.RecordRow {
        let row = schema.record_new();
        row.int_vals[0] = id;
        row.int_vals[1] = age;
        return row;
    }

    // === 테스트 1: SELECT * (모든 행 조회) ===

    func test_pipeline_select_all() {
        print("\n=== Test 1: Pipeline SELECT * ===");

        // 1. 테이블 생성 (id, age)
        let s = make_emp_schema();
        let t = schema.table_new(s);
        let r0 = assert_eq_i32(t.row_count, 0, "initial row_count == 0");
        print_result(r0);

        // 2. 10개 행 삽입 (id=1-10, age=20-29)
        let i = 0;
        for i = 0; i < 10; i = i + 1 {
            let row = make_emp_row(i64(i + 1), i64(20 + i));
            t.table_insert(row);
        }
        let r1 = assert_eq_i32(t.row_count, 10, "after insert row_count == 10");
        print_result(r1);

        // 3. 쿼리 실행 (SELECT * FROM emp)
        let q = query.query_table(t);
        let qr = query.execute(t, q);
        let r2 = assert_eq_i32(qr.error_code, query.QUERY_OK, "query error_code == QUERY_OK");
        print_result(r2);

        // 4. 결과 검증
        let r3 = assert_eq_i32(qr.row_count, 10, "result row_count == 10");
        print_result(r3);

        // 5. 첫 번째 행 검증 (id=1, age=20)
        let first_row = t.table_get_row(qr.row_indices[0]);
        let r4 = assert_eq_i64(first_row.int_vals[0], 1, "first row id == 1");
        print_result(r4);

        let r5 = assert_eq_i64(first_row.int_vals[1], 20, "first row age == 20");
        print_result(r5);

        print("Test 1 completed");
    }

    // === 테스트 2: WHERE 조건 필터링 ===

    func test_pipeline_where() {
        print("\n=== Test 2: Pipeline WHERE ===");

        // 1. 테이블 생성
        let s = make_emp_schema();
        let t = schema.table_new(s);

        // 2. 20개 행 삽입 (age=1-20)
        let i = 0;
        for i = 0; i < 20; i = i + 1 {
            let row = make_emp_row(i64(i + 1), i64(i + 1));
            t.table_insert(row);
        }
        let r1 = assert_eq_i32(t.row_count, 20, "inserted 20 rows");
        print_result(r1);

        // 3. 쿼리 실행 (SELECT * FROM emp WHERE age > 10)
        let q = query.query_table(t);
        q.where_int(1, query.OP_GT, 10);  // age 컬럼(idx=1) > 10
        let qr = query.execute(t, q);

        // 4. 결과 검증
        let r2 = assert_eq_i32(qr.error_code, query.QUERY_OK, "where query OK");
        print_result(r2);

        // age > 10 → 11-20 = 10개
        let r3 = assert_eq_i32(qr.row_count, 10, "WHERE age>10 count == 10");
        print_result(r3);

        // 5. 첫 결과 행 검증 (age=11)
        let first_result = t.table_get_row(qr.row_indices[0]);
        let r4 = assert_true(first_result.int_vals[1] > 10, "first result age > 10");
        print_result(r4);

        print("Test 2 completed");
    }

    // === 테스트 3: ORDER BY + LIMIT (정렬 및 페이징) ===

    func test_pipeline_sort_limit() {
        print("\n=== Test 3: Pipeline ORDER BY + LIMIT ===");

        // 1. 테이블 생성
        let s = make_emp_schema();
        let t = schema.table_new(s);

        // 2. 15개 행 삽입 (score 역순: 15,14,13,...,1)
        let i = 0;
        for i = 0; i < 15; i = i + 1 {
            let row = make_emp_row(i64(i + 1), i64(15 - i));  // id=1-15, age=15,14,...,1
            t.table_insert(row);
        }
        let r1 = assert_eq_i32(t.row_count, 15, "inserted 15 rows");
        print_result(r1);

        // 3. 쿼리 실행 (SELECT * FROM emp ORDER BY age LIMIT 5)
        let q = query.query_table(t);
        q.order_by_int(1, true);   // age ASC
        q.set_limit(5);
        let qr = query.execute(t, q);

        // 4. 결과 검증
        let r2 = assert_eq_i32(qr.error_code, query.QUERY_OK, "order by query OK");
        print_result(r2);

        let r3 = assert_eq_i32(qr.row_count, 5, "ORDER BY LIMIT 5 count == 5");
        print_result(r3);

